import 'dart:convert';
import 'dart:io';

/// Generate the app's source allowlist from the backend's reviewed catalogue.
void main() {
  final sources =
      jsonDecode(
            File(
              'supabase/functions/_shared/coach_sources.json',
            ).readAsStringSync(),
          )
          as List;
  String literal(Object? value) => jsonEncode(value).replaceAll(r'$', r'\$');
  final out = StringBuffer(
    '// Generated by tool/sync_coach_sources.dart. Do not edit manually.\n'
    "part of 'coach_sources.dart';\n\n"
    'const coachSources = <CoachSource>[\n',
  );
  for (final source in sources.cast<Map<String, dynamic>>()) {
    out.writeln('  CoachSource(');
    for (final (field, key) in [
      ('id', 'id'),
      ('title', 'title'),
      ('url', 'url'),
      ('checked', 'checked'),
      ('summaryDe', 'summary_de'),
      ('summaryEn', 'summary_en'),
    ]) {
      out.writeln('    $field: ${literal(source[key])},');
    }
    out.writeln('  ),');
  }
  out.writeln('];');
  File('lib/features/coach/domain/coach_sources.g.dart')
    ..createSync(recursive: true)
    ..writeAsStringSync(out.toString());

  String html(Object? value) =>
      const HtmlEscape().convert(value.toString()).replaceAll('&#47;', '/');
  for (final english in [false, true]) {
    final path = 'web/legal/${english ? 'en/' : ''}gesundheit-quellen.html';
    final title = english
        ? 'Health information and sources'
        : 'Gesundheitshinweise und Quellen';
    final note = english
        ? 'Lookin provides general information about food and movement. Consult a qualified professional before making medical decisions. AI answers can be wrong. Sources do not validate personal calorie or protein targets, recipe nutrition or photo estimates. Check estimates before saving. Custom foods are your own unverified entries; use current packaging information. Source catalogue updated: 31 October 2026.'
        : 'Lookin gibt allgemeine Orientierung zu Ernährung und Bewegung. Hole vor medizinischen Entscheidungen fachlichen Rat ein. KI-Antworten können falsch sein. Quellen bestätigen keine persönlichen Kalorien- oder Proteinziele, Rezeptnährwerte oder Fotoschätzungen. Prüfe Schätzungen vor dem Speichern. Eigene Lebensmittel sind deine ungeprüften Eingaben; nutze aktuelle Verpackungsangaben. Quellenstand: 31.10.2026.';
    final links = sources
        .map(
          (source) =>
              '<li><p><a href="${html(source['url'])}" rel="noopener noreferrer">${html(source['title'])}</a></p><p>${html(source[english ? 'summary_en' : 'summary_de'])}</p></li>',
        )
        .join('\n');
    final privacy = english ? 'Privacy Policy' : 'Datenschutz';
    final terms = english ? 'Terms' : 'AGB';
    File(path).writeAsStringSync('''<!doctype html>
<!-- Generated by tool/sync_coach_sources.dart. -->
<html lang="${english ? 'en' : 'de'}"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="referrer" content="no-referrer">
<title>${html(title)} – Lookin</title>
<link rel="stylesheet" href="${english ? '../' : ''}legal.css">
</head><body><main><nav><a href="datenschutz.html">$privacy</a> <a href="agb.html">$terms</a></nav>
<h1>${html(title)}</h1><p>${html(note)}</p>
<ul>$links</ul>
<p>${english ? 'Source links open external websites, which process connection data under their own privacy notices. Lookin does not attach chat, profile or diary data to the links.' : 'Quellenlinks öffnen externe Webseiten. Dort gelten die jeweiligen Datenschutzhinweise für Verbindungsdaten. Lookin hängt keine Chat-, Profil- oder Tagebuchdaten an die Links an.'}</p>
</main></body></html>
''');
  }
}
